<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../api';const config=ref<any>({payment:{},live:{},registration:{}});onMounted(async()=>config.value=(await api.get('/admin/config')).data);</script><template><section class="page"><h1 class="page-title">系统配置</h1><el-alert title="密钥仅可覆盖更新，平台不会回显明文" type="warning"/><div class="cards" style="margin-top:18px"><div class="card"><h3>支付配置</h3><p>服务商：{{config.payment.provider}}</p><p>商户号：{{config.payment.merchantId}}</p><p>API 密钥：<code>{{config.payment.apiKey}}</code></p><el-button>更新支付配置</el-button></div><div class="card"><h3>直播配置</h3><p>服务商：{{config.live.provider}}</p><p>应用 ID：{{config.live.appId}}</p><p>Secret：<code>{{config.live.secretKey}}</code></p><el-button>更新直播配置</el-button></div><div class="card"><h3>账号策略</h3><p>开放注册：{{config.registration.enabled?'是':'否'}}</p><p>注册审核：{{config.registration.reviewRequired?'是':'否'}}</p></div></div></section></template>
